#!/bin/bash
# .claude/on-implement-commit.sh
# Called by the post-commit hook on every implement( commit.
# Starts the local dev environment and resets the 60-minute idle timer.
# Generated by Levain — edit commands in levain.yml.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(dirname "$SCRIPT_DIR")"
TIMESTAMP_FILE="$SCRIPT_DIR/local-env.timestamp"
PID_FILE="$SCRIPT_DIR/local-env.pid"
RUN_PID_FILE="$SCRIPT_DIR/local-env-run.pid"
RUN_LOG="$SCRIPT_DIR/local-env-run.log"
IDLE_SECONDS=3600

# Quoted heredocs, not "…": the commands are eval'd later, after FEATURE_PORT
# and PORT are exported below. Double quotes expanded `$PORT` here, at
# assignment, to nothing — and a `"` inside a command ended the string
# (LVI-034).
START_CMD=$(cat <<'LV_LOCAL_CMD'
{{local_start_command}}
LV_LOCAL_CMD
)
DEPLOY_CMD=$(cat <<'LV_LOCAL_CMD'
{{local_deploy_command}}
LV_LOCAL_CMD
)
STOP_CMD=$(cat <<'LV_LOCAL_CMD'
{{local_stop_command}}
LV_LOCAL_CMD
)

# ── Plan-scoped container identity ────────────────────────────────────────
# Every command below is eval'd, and the compose file they drive reads
# COMPOSE_PROJECT_NAME and FEATURE_PORT from the environment. Relying on the
# caller to have exported them is what WFI-033 reports: `start` invoked by hand
# in a feature worktree brought PLN-002 up as `...-pln001` on 8101, and because
# `start` does not rebuild, that container can serve an image built for a
# different plan — a human test then runs against the wrong build.
#
# So derive them here instead of trusting the caller. This script knows which
# worktree it is in, and a feature worktree carries `.plan-ref`; nothing else is
# needed. An already-exported value wins, so an explicit override still works.
#
# The formula is duplicated from scripts/*/lv-plan-port.sh, which remains the
# authority. `tests/client-reports.sh` asserts the two agree, because a silent
# divergence here is exactly the class of bug this block exists to kill.
if [ -f "$PROJECT_DIR/.plan-ref" ]; then
    _plan_ref=$(tr -d '[:space:]' < "$PROJECT_DIR/.plan-ref")
    _plan_num=$(printf '%s' "$_plan_ref" | grep -oE '[0-9]+' | head -1)
    if [ -n "$_plan_num" ]; then
        _plan_num=$((10#$_plan_num))
        export FEATURE_PORT="${FEATURE_PORT:-$((8100 + _plan_num))}"
        export PORT="${PORT:-$FEATURE_PORT}"   # as lv-docker-up.sh exports it
        export COMPOSE_PROJECT_NAME="${COMPOSE_PROJECT_NAME:-$(printf '{{project_slug}}-pln%03d' "$_plan_num")}"
        echo "local-env: $COMPOSE_PROJECT_NAME on port $FEATURE_PORT (from .plan-ref)"
    fi
fi

_write_timestamp() {
    date +%s > "$TIMESTAMP_FILE"
}

_kill_watcher() {
    if [ -f "$PID_FILE" ]; then
        local pid
        pid=$(cat "$PID_FILE")
        if kill -0 "$pid" 2>/dev/null; then
            kill "$pid" 2>/dev/null || true
        fi
        rm -f "$PID_FILE"
    fi
}

# ── The command runs detached, in its own process group ──────────────────
# The post-commit hook calls this script, and git waits for the hook — and for
# anything still holding the hook's stdout — before `git commit` returns. A
# command that stays up (`exec python3 -m http.server $PORT`, `dotnet run`)
# therefore hung every implement( commit, and every lv-progress-tick.sh commit
# behind it, until someone killed the server (LVI-037). So the command never
# runs in the foreground: it gets its own process group (so a server's children
# go with it), /dev/null for stdin, and RUN_LOG for output; its group id goes in
# RUN_PID_FILE. A `docker compose up -d` exits on its own; a server stays up and
# is what the next deploy, `stop`, or the idle timer ends.
_kill_run() {
    if [ -f "$RUN_PID_FILE" ]; then
        local pgid
        pgid=$(tr -d '[:space:]' < "$RUN_PID_FILE")
        if [ -n "$pgid" ] && kill -0 "$pgid" 2>/dev/null; then
            kill -TERM -- "-$pgid" 2>/dev/null || kill -TERM "$pgid" 2>/dev/null || true
        fi
        rm -f "$RUN_PID_FILE"
    fi
}

_run_detached() {
    _kill_run   # a redeploy replaces the previous run, never stacks on it
    : > "$RUN_LOG"
    # `cd` on its own line: `cd … && nohup … &` backgrounds the whole list, in a
    # subshell that holds the hook's stdout until the server exits — the hang
    # this function exists to prevent — and $! names that subshell, not the group.
    ( cd "$PROJECT_DIR" || exit 1
      nohup perl -e 'setpgrp(0, 0); exec "bash", "-c", $ARGV[0]' "$1" \
          >>"$RUN_LOG" 2>&1 </dev/null &
      echo $! > "$RUN_PID_FILE" )
    echo "local-env: running detached (pgid $(cat "$RUN_PID_FILE")) — log: $RUN_LOG"
}

_start_watcher() {
    local stop_cmd="$STOP_CMD"
    local timestamp_file="$TIMESTAMP_FILE"
    local pid_file="$PID_FILE"
    local idle_seconds="$IDLE_SECONDS"
    local project_dir="$PROJECT_DIR"
    local run_pid_file="$RUN_PID_FILE"

    nohup bash -c "
        while true; do
            sleep 60
            [ -f \"$timestamp_file\" ] || exit 0
            last=\$(cat \"$timestamp_file\")
            now=\$(date +%s)
            age=\$((now - last))
            if [ \$age -gt $idle_seconds ]; then
                echo \"local-env: idle timeout — stopping\"
                if [ -f \"$run_pid_file\" ]; then
                    pg=\$(tr -d '[:space:]' < \"$run_pid_file\")
                    [ -n \"\$pg\" ] && kill -TERM -- \"-\$pg\" 2>/dev/null
                    rm -f \"$run_pid_file\"
                fi
                cd \"$project_dir\" && $stop_cmd
                rm -f \"$timestamp_file\" \"$pid_file\"
                exit 0
            fi
        done
    " > "$SCRIPT_DIR/local-env.log" 2>&1 </dev/null &

    echo $! > "$PID_FILE"
    disown $! 2>/dev/null || true
}

case "${1:-deploy}" in
    start)
        if [ -z "$START_CMD" ]; then
            echo "local-env: local_start_command is not set in levain.yml" >&2
            exit 1
        fi
        echo "local-env: starting..."
        _run_detached "$START_CMD"
        _write_timestamp
        _kill_watcher
        _start_watcher
        echo "local-env: started — auto-stop in 60 minutes"
        ;;

    deploy)
        local_cmd="${DEPLOY_CMD:-$START_CMD}"
        if [ -z "$local_cmd" ]; then
            echo "local-env: local_deploy_command is not set in levain.yml" >&2
            exit 1
        fi
        echo "local-env: deploying..."
        _run_detached "$local_cmd"
        _write_timestamp
        _kill_watcher
        _start_watcher
        echo "local-env: deployed — timer reset to 60 minutes"
        ;;

    stop)
        # A detached run is stopped by its process group, so a project whose
        # command is a plain server needs no local_stop_command.
        if [ -z "$STOP_CMD" ] && [ ! -f "$RUN_PID_FILE" ]; then
            echo "local-env: local_stop_command is not set in levain.yml" >&2
            exit 1
        fi
        echo "local-env: stopping..."
        _kill_watcher
        _kill_run
        if [ -n "$STOP_CMD" ]; then
            cd "$PROJECT_DIR" && eval "$STOP_CMD"
        fi
        rm -f "$TIMESTAMP_FILE"
        echo "local-env: stopped"
        ;;

    status)
        if [ ! -f "$TIMESTAMP_FILE" ]; then
            echo "local-env: stopped"
        else
            last=$(cat "$TIMESTAMP_FILE")
            now=$(date +%s)
            elapsed=$(( (now - last) / 60 ))
            remaining=$(( (IDLE_SECONDS - (now - last)) / 60 ))
            if [ $remaining -le 0 ]; then
                echo "local-env: timer expired (stopping soon)"
            else
                echo "local-env: running — ${elapsed}m elapsed, ~${remaining}m remaining"
            fi
        fi
        ;;

    *)
        echo "Usage: on-implement-commit.sh <start|deploy|stop|status>"
        exit 1
        ;;
esac
